sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_srcSel;
uniform float3 amzp_moveXYZ;
uniform float3 amzp_orient;
uniform float amzp_parStr;
uniform float3 amzp_rotInf;
uniform float amzp_depthSpan;
uniform float amzp_nearZ;
uniform float amzp_AMOUNT;
uniform float amzp_fieldSize;
uniform float amzp_scale;
uniform float2 amzp_stretch;
uniform float2 amzp_position;
uniform float amzp_angle;
uniform float amzp_seed;
uniform float amzp_size;
uniform float amzp_reach;
uniform float amzp_bright;
uniform float amzp_blink;
uniform float amzp_blinkSpeed;
uniform float amzp_colorMode;
layout(color) uniform half4 amzp_color1;
layout(color) uniform half4 amzp_color2;
uniform float amzp_blendMode;
uniform float amzp_blackBg;
uniform float amzp_alpha;
uniform float amzp_overdrawOn;
    uniform float3 nmCamPos;
    uniform float3 nmCamRot;
    uniform float nmCamZoom;
    uniform float nmCamPersp;
    uniform float nmCamOn;
    uniform float3 nmLayPos;
    uniform float3 nmLayRot;
    uniform float2 nmScene;
    float h11(float n) {
        float so = fract(amzp_seed * 0.1317) * 97.0 + fract(amzp_seed * 0.4371) * 13.0;
        float2 p = fract(float2(n * 0.1031 + so, n * 0.1030 + so * 0.731));
        p += dot(p, p.yx + 33.33);
        return fract((p.x + p.y) * p.x);
    }
    float3 rot3(float3 v, float3 a) {
        float3 r = a * 0.0174533;
        float c = cos(r.x), s = sin(r.x);
        v = float3(v.x, c * v.y - s * v.z, s * v.y + c * v.z);
        c = cos(r.y); s = sin(r.y);
        v = float3(c * v.x + s * v.z, v.y, -s * v.x + c * v.z);
        c = cos(r.z); s = sin(r.z);
        return float3(c * v.x - s * v.y, s * v.x + c * v.y, v.z);
    }
    void amzRender() {
        float4 tex = amzTexture(0, amzScreenNorm());
        if (!(amzp_overdrawOn>0.5) && tex.a <= 0.0001) { amzOutput=float4(0.0); return; }
        float psc = nmScene.y > 1.0 ? screen.zw.y / nmScene.y : screen.zw.y / max(screen.zw.y, 1.0);
        float2 pix = float2(amzScreenNorm().x, 1.0 - amzScreenNorm().y) * screen.zw;
        float2 q = pix - screen.zw * 0.5;
        float zoom = nmCamZoom > 1.0 ? nmCamZoom : 1500.0;
        float3 P = nmCamPos;
        float3 R = nmCamRot;
        float fw = nmCamPos.z + zoom;
        if (int(amzp_srcSel) == 1) { P = nmLayPos; R = nmLayRot; fw = nmLayPos.z; }
        else if (int(amzp_srcSel) == 2) { P = nmCamPos + nmLayPos; R = nmCamRot + nmLayRot; fw = nmCamPos.z + zoom + nmLayPos.z; }
        float3 C = float3(P.xy, fw) * amzp_parStr + amzp_moveXYZ;
        float3 turn = R * amzp_rotInf + amzp_orient;
        float3 Rv = float3(-turn.x, -turn.y, turn.z);
        float T = max(amzp_fieldSize, 10.0);
        float sc0 = max(amzp_scale, 0.01);
        float2 stv = max(amzp_stretch, float2(0.01));
        float span = max(amzp_depthSpan, 10.0);
        float nz = max(amzp_nearZ, 1.0);
        float ca = cos(radians(amzp_angle)), sa = sin(radians(amzp_angle));
        float3 col = float3(0.0);
        for (int i = 0; i < 80; i++) {
            if (float(i) >= float(amzp_AMOUNT)) break;
            float fi = float(i);
            float2 p = float2(h11(fi * 1.31 + 11.0), h11(fi * 2.17 + 37.0)) * T;
            float dz = h11(fi * 3.73 + 71.0) * span;
            float2 rel = mod(p + amzp_position - C.xy + T * 0.5, T) - T * 0.5;
            float zr = mod(dz - C.z, span) - span * 0.5;
            float edge = max(max(abs(rel.x), abs(rel.y)) / (T * 0.5), abs(zr) / (span * 0.5));
            float fade = 1.0 - smoothstep(0.75, 1.0, edge);
            float2 rr = rel * stv * sc0;
            rr = float2(ca * rr.x - sa * rr.y, sa * rr.x + ca * rr.y);
            float3 v = rot3(float3(rr, zr + zoom), Rv);
            if (v.z <= nz) continue;
            fade *= smoothstep(nz, nz * 2.5, v.z);
            if (fade <= 0.0001) continue;
            float si = zoom / v.z;
            float2 off = v.xy * psc * si;
            float Spx = max(amzp_size * sc0 * psc * si, 0.25);
            float r = length(q - off);
            float cut = 1.0 - smoothstep(Spx * amzp_reach * 0.35, Spx * amzp_reach, r);
            if (cut <= 0.0) continue;
            float I = pow(Spx / max(r, Spx * 0.05), 1.2) * cut;
            float ph = h11(fi * 5.31 + 3.0) * 6.2832;
            float sp = amzp_blinkSpeed * (0.5 + h11(fi * 6.77 + 9.0));
            float tw = 1.0 - amzp_blink * 0.5 * (1.0 + sin(time * sp + ph));
            float3 sc = float3(h11(fi * 7.1 + 1.0), h11(fi * 8.3 + 2.0), h11(fi * 9.7 + 4.0));
            if (int(amzp_colorMode) == 1) sc = mix(amzp_color1.rgb, amzp_color2.rgb, h11(fi * 7.9 + 5.0));
            col += sc * I * tw * fade;
        }
        col = clamp(col * amzp_bright, 0.0, 1.0);
        float al = max(col.r, max(col.g, col.b));
        float mask = 1.0;
        float4 res;
        if (int(amzp_blendMode) == 0) {
            float4 stars = float4(col, (amzp_blackBg>0.5) ? 1.0 : al);
            res = ((amzp_blackBg>0.5) ? float4(col, 1.0) : stars) * mask;
        } else if (int(amzp_blendMode) == 1) {
            float oa = max(tex.a, al * mask);
            res = float4(min(tex.rgb + col * mask, float3(oa)), oa);
        } else if (int(amzp_blendMode) == 2) {
            float3 cm = col * mask;
            float oa = max(tex.a, al * mask);
            res = float4(min(tex.rgb + cm - tex.rgb * cm, float3(oa)), oa);
        } else {
            float3 b = tex.a > 0.0001 ? tex.rgb / tex.a : float3(0.0);
            float3 tint = col / max(al, 0.0001);
            res = float4(b * mix(float3(1.0), tint, al * mask) * tex.a, tex.a);
        }
        amzOutput = mix(tex, res, amzp_alpha);
        if (!(amzp_overdrawOn>0.5)) amzOutput *= tex.a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
